"""Recommendation tasks, grounded in services' public explanations."""
from common import *


def example(context, items, caption):
    return '<figure class="rec-example"><div class="rec-pair"><div><span class="rec-label">入力の手がかり</span><p>'+context+'</p></div><div><span class="rec-label">出力：おすすめの順序</span><ol>'+''.join('<li>'+item+'</li>' for item in items)+'</ol></div></div><figcaption>'+caption+' 掲載した履歴・候補・順序は教材用の架空例で、実サービスの画面や推論結果ではありません。</figcaption></figure>'


def body():
    out=sec('recommendation','推薦：その人・その場面に合う候補を薦める',p('Netflixで次に観る作品、Spotifyで聴く曲、通販で買う商品。推薦（recommendation）は、多数の候補から、その人や今の状況に合いそうなものを選んで提示するタスクです。全員に同じ人気順を見せる場合もありますが、個人化した推薦では、利用履歴などによって候補や順序が変わります。')+table(['身近な場面','何を薦めるか','違いを見る点'],[
        ('<a href="#rec-netflix">Netflix</a>','映画・ドラマと、ホームの棚','作品の選択だけでなく、どの棚を上に置くか'),
        ('<a href="#rec-youtube">YouTube</a>','ホームの動画・次に再生する動画','普段の好みと、今観ている動画の両方'),
        ('<a href="#rec-spotify">Spotify</a>','曲・個人向けプレイリスト','知っている曲の再生と、知らない曲の発見'),
        ('<a href="#rec-shopping">Amazonなどの通販</a>','商品・関連商品','代わりになる商品と、一緒に使う商品'),
        ('<a href="#rec-more">ニュース・SNS</a>','記事・投稿・フォロー候補','新しさや、推薦が偏りすぎないこと'),
        ('<a href="#rec-more">求人・学習サービス</a>','求人・講座・次に解く問題','希望条件や、今の理解度との適合')]))
    out+=sec('rec-netflix','Netflix：同じホームでも、薦める作品と棚が違う',p('Netflixは視聴履歴や評価、好みの似た利用者、ジャンル・出演者などの作品情報を手がかりに推薦します。ホームでは、棚の選択、棚に入れる作品、その中の並び順にも個人化が入ります。<a href="https://help.netflix.com/en/node/100639">Netflix公式：推薦の仕組み</a>。')+example('宇宙探査の作品をよく観る人。<br>最近も宇宙のドキュメンタリーを視聴。',['未視聴の宇宙探査ドキュメンタリー','惑星を舞台にしたSF映画','自然科学のドキュメンタリー'],'「好きな作品と同じジャンル」以外にも候補を広げる例。')+p('例えば別の人が恋愛ドラマをよく観るなら、同じ作品集合からでも違う作品や棚を目立たせる、と考えられます。出力は「この映画を好きになる確率」のような一つの数値だけでなく、最終的にユーザーが見るホーム画面の構成につながります。'))
    out+=sec('rec-youtube','YouTube：ホームと「次の動画」では文脈が違う',p('YouTubeの公式説明では、ホームの推薦は主に視聴履歴、次の動画の推薦は主に現在観ている動画を手がかりにします。高評価・低評価、「興味なし」などの反応も使います。<a href="https://support.google.com/youtube/answer/16089387?hl=en">YouTube公式：推薦の仕組み</a>。')+example('普段は料理動画をよく観る人が、<br>今は「パンクした自転車の修理」を視聴中。',['タイヤを外してチューブを交換する方法','修理後に空気漏れを確認する方法','自転車の日常点検'],'「今やっていること」に合う次の動画を薦める例。')+p('ホームなら料理の動画が候補になっても、修理中の「次の動画」では作業の続きを助ける動画が役立ちそうです。推薦では「この人は何が好きか」だけでなく、「今、何をしているか」も重要です。検索が入力された言葉から候補を探すのに対して、推薦は検索語がなくても履歴や現在の動画を出発点にできます。'))
    out+=sec('rec-spotify','Spotify：好きな曲から、まだ知らない曲へ',p('Spotifyは再生・保存・スキップなどの聴き方や、好みが似た人の聴き方を使って個人向けのプレイリストを作ります。Discover Weeklyは、気に入りそうな曲との出会いを作る例です。<a href="https://support.spotify.com/dm/article/find-playlists/">Spotify公式：プレイリストについて</a>。')+example('静かなアコースティック曲をよく聴き、<br>気に入った曲を保存している。',['まだ聴いたことのない歌手のアコースティック曲','好きな歌手と雰囲気が近い曲','少し違うジャンルの落ち着いた曲'],'好みに合う曲と、新しい発見になる曲を混ぜる例。')+p('すでに好きな曲だけを薦めれば安心して聴けますが、新しい歌手には出会いにくくなります。逆に未知の曲ばかりでは好みから外れるかもしれません。「合いそう」と「新しい」の両方を考えることが推薦の面白い点です。スキップも、曲が嫌いだったのか、今の気分に合わなかったのかは行動だけでは決まりません。'))
    out+=sec('rec-shopping','通販：似た商品と、一緒に使う商品を分ける',p('Amazonが公開している推薦技術の歴史では、商品間の購入の関係を使うitem-to-item協調フィルタリングが紹介されています。「同じ人たちが買っている」という関係から、商品同士を結び付ける発想です。現在のすべての推薦欄がこの方法だけで動いているという意味ではありません。<a href="https://www.amazon.science/the-history-of-amazons-recommendation-algorithm">Amazon Science：推薦技術の歴史</a>。')+example('コーヒードリッパーを購入した人に、<br>一緒に使う商品を薦めたい。',['形とサイズが合うペーパーフィルター','コーヒー豆','抽出量を測るスケール'],'同じカテゴリではない商品も候補になる例。')+p('購入前に比較したいなら「別のドリッパー」、購入後に使い始めたいなら「対応するフィルター」が役立ちます。前者は代替品、後者は補完品です。見た目や商品説明が似ているだけでは、こうした用途の違いを捉えきれません。'))
    out+=sec('rec-more','ニュース・人・仕事・学ぶ順序も推薦できる',p('推薦対象は映画や商品に限りません。次は、特定サービスの実装ではなく、タスクを設計する例です。')+table(['応用','入力の例 → 出力','役立つ推薦にするには'],[
        ('ニュース','読んだ記事・関心分野 → 記事の順位','関心との一致に加え、新しさや情報源の多様性を見る'),
        ('SNSのフォロー候補','フォロー関係・関心 → アカウントの候補','共通の知人が多い人と、関心が近い人は異なる'),
        ('求人','経験・希望職種・勤務地 → 求人の候補','クリックされやすさだけでなく、条件や経験との適合を見る'),
        ('学習教材','解答履歴・習得した内容 → 次の問題や講座','簡単すぎず難しすぎず、学習が進む候補を考える'),
        ('旅行・飲食店','行き先・予算・好み → 宿や店の候補','好みが合っていても、空きや営業時間が合わなければ使えない')]))
    out+=sec('rec-how','候補を集め、順位を付ける：何を手がかりにするか',flow([('履歴・今の状況','入力',BLUE),('候補を集める','多数から絞る'),('順位を付ける','合いそうな順へ'),('提示・反応','次の観測になる',ORANGE)],'推薦システムの一般的な構成例。各サービスの内部構成をそのまま再現したものではない。')+table(['考え方','映画の教材例'],[
        ('内容に基づく推薦','宇宙の映画が好き → ジャンルや説明が近い未視聴の映画'),
        ('協調フィルタリング','AさんとBさんは作品X・Yが好き → Bさんが好きな作品ZをAさんにも薦める'),
        ('組み合わせる','視聴の関係と作品の内容、最近の行動を合わせて候補を評価する')])+p('協調フィルタリングは、利用者と候補への反応の関係を使います。行列分解や深層モデルなどで、その関係を表現できます。利用者と商品を結ぶグラフにして<a href="gnn.html">GNN</a>で扱う方法もあります。推薦は「何を薦めるか」というタスクなので、一つのモデルに限定されません。')+p('履歴がまだない新規利用者や新商品は、反応の関係だけでは薦めにくい対象です。最初に好みを選んでもらう、内容の特徴を使う、といった方法が考えられます。'))
    out+=sec('rec-evaluation','クリックされたら、よい推薦なのか',p('押した動画をすぐ閉じる、買った商品を返品する、といった場合もあります。クリック・視聴・購入は便利な学習信号ですが、そのまま満足度とは限りません。例えば動画なら視聴後の満足、学習教材なら理解の進み方など、用途に合った評価が必要です。')+p('また、表示しなかった候補への反応は観測できません。「選ばれなかった」ことと「見たうえで嫌いだった」ことは違います。上に出した作品ほど観られ、その履歴からさらに薦められる循環も起こります。的中率に加え、多様性、新しい候補を発見できるか、特定の候補に偏りすぎないかも見ます。'))
    return out
